/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return api.state.isLoading || api.state.hideRecordNotFound;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.state.hideRecordNotFound || api.state.isLoading;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const configScreens = ['setup-type', 'product-list', 'product-desc'];
  if ( api.context.props.id != -1 && configScreens.includes(api.context.props.configure)) {
    return true;
  }
	return false;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {

	return api.state.processId !== "-1";
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {

	return api.state.processId !== "-1";
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    if (api.context.props.id !== '-1' && !api.state.isLoading) {
        if (api.data.get_setup_info.result && api.state.pageInput.roles) {
            let setupRoles = api.state.pageInput.roles.split(",");
            return setupRoles.map(role => {return {id: role, label: role};});
        }
    }
    return;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    let configure = api.context.props.configure;
    let supportedConfigs = ['setup-type', 'product-list', 'product-desc'];
    let disabled = true;
    if (supportedConfigs.includes(configure)){
      disabled = api.state.disableContinue[configure];
    } else {
      disabled = api.state.disableContinue['basic'];
    }
    return disabled;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {

    const configScreens = ['setup-type', 'product-list', 'product-desc'];
    if (api.context.props.id != -1 && configScreens.includes(api.context.props.configure)) {
        return 'Previous';
    }
    return '';
}
